package com.bookeat.membership.service;
import com.bookeat.membership.dto.MembershipDtos.*;import com.bookeat.exception.*;import com.bookeat.payment.gateway.GatewayPort;import com.bookeat.payment.service.PaymentRules;import lombok.RequiredArgsConstructor;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.sql.*;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor
public class MembershipService {
 private final JdbcTemplate jdbc; private final GatewayPort gateway;
 private Plan map(ResultSet r,int n)throws SQLException {String raw=r.getString("benefits");List<String>b=raw==null||raw.isBlank()?List.of():Arrays.stream(raw.split("\\n")).filter(s->!s.isBlank()).toList();return new Plan(r.getObject("id",UUID.class),r.getString("name"),r.getString("description"),r.getBigDecimal("price"),r.getString("billing_period"),r.getString("badge"),b,r.getInt("display_order"),r.getBoolean("active"),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant());}
 public List<Plan> active(){return jdbc.query("select * from membership_plans where active=true order by display_order,name",this::map);} public List<Plan> all(){return jdbc.query("select * from membership_plans order by display_order,name",this::map);}
 @Transactional public Plan create(SavePlan q){UUID id=UUID.randomUUID();jdbc.update("insert into membership_plans(id,name,description,price,billing_period,badge,benefits,display_order,active) values(?,?,?,?,?,?,?,?,?)",id,q.name().trim(),q.description(),q.price(),q.billingPeriod(),q.badge(),q.benefits()==null?null:String.join("\n",q.benefits()),q.displayOrder(),q.active());return byId(id);}
 @Transactional public Plan update(UUID id,SavePlan q){if(jdbc.update("update membership_plans set name=?,description=?,price=?,billing_period=?,badge=?,benefits=?,display_order=?,active=?,updated_at=CURRENT_TIMESTAMP,version=version+1 where id=?",q.name().trim(),q.description(),q.price(),q.billingPeriod(),q.badge(),q.benefits()==null?null:String.join("\n",q.benefits()),q.displayOrder(),q.active(),id)!=1)throw new ApiException(ErrorCode.RESOURCE_NOT_FOUND);return byId(id);}
 private Plan byId(UUID id){var rows=jdbc.query("select * from membership_plans where id=?",this::map,id);if(rows.isEmpty())throw new ApiException(ErrorCode.RESOURCE_NOT_FOUND);return rows.get(0);} private UUID customer(UUID userId){return jdbc.queryForObject("select id from customers where user_id=?",UUID.class,userId);}
 public Checkout startCheckout(UUID userId,UUID planId){if(!gateway.enabled())throw new ApiException(ErrorCode.PAYMENT_GATEWAY_UNAVAILABLE);var p=byId(planId);if(!p.active())throw new ApiException(ErrorCode.VALIDATION_FAILED);UUID c=customer(userId),id=UUID.randomUUID();jdbc.update("update membership_checkout set status='CANCELLED' where customer_id=? and status='PENDING'",c);jdbc.update("insert into membership_checkout(id,customer_id,plan_id,amount,status) values(?,?,?,?,'PENDING')",id,c,planId,p.price());GatewayPort.GatewayOrder order;try{order=gateway.create(id,p.price());}catch(RuntimeException ex){jdbc.update("update membership_checkout set status='FAILED' where id=?",id);throw ex;}jdbc.update("update membership_checkout set gateway_order_id=? where id=?",order.id(),id);return new Checkout(id,planId,p.name(),p.price(),"PENDING",order.id(),gateway.publicKey(),"INR");}
 @Transactional public Subscription verifyAndActivate(UUID userId,UUID checkoutId,VerifyPayment q){UUID c=customer(userId);var rows=jdbc.query("select plan_id,amount,status,gateway_order_id from membership_checkout where id=? and customer_id=? for update",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getBigDecimal(2),r.getString(3),r.getString(4)},checkoutId,c);if(rows.isEmpty())throw new ApiException(ErrorCode.RESOURCE_NOT_FOUND);UUID planId=(UUID)rows.get(0)[0];var amount=(java.math.BigDecimal)rows.get(0)[1];String status=(String)rows.get(0)[2],orderId=(String)rows.get(0)[3];if("PAID".equals(status)){var current=current(userId);if(current!=null&&current.planId().equals(planId))return current;throw new ApiException(ErrorCode.PAYMENT_INVALID);}if(!"PENDING".equals(status)||orderId==null||!gateway.verifyCheckout(orderId,q.gatewayPaymentId(),q.signature()))throw new ApiException(ErrorCode.PAYMENT_INVALID);var proof=gateway.fetchPayment(q.gatewayPaymentId());if(!orderId.equals(proof.orderId())||proof.amount()!=PaymentRules.minor(amount)||!"INR".equals(proof.currency())||!"captured".equals(proof.status())||proof.refunded()!=0)throw new ApiException(ErrorCode.PAYMENT_INVALID);jdbc.update("update membership_checkout set status='PAID',gateway_payment_id=?,payment_method=?,paid_at=CURRENT_TIMESTAMP,verified_at=CURRENT_TIMESTAMP where id=?",proof.id(),proof.method(),checkoutId);return activate(c,planId);}
 @Transactional public boolean webhookCaptured(GatewayPort.GatewayPayment proof){var rows=jdbc.query("select id,customer_id,plan_id,amount,status from membership_checkout where gateway_order_id=? for update",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getBigDecimal(4),r.getString(5)},proof.orderId());if(rows.isEmpty())return false;UUID checkoutId=(UUID)rows.get(0)[0],c=(UUID)rows.get(0)[1],planId=(UUID)rows.get(0)[2];var amount=(java.math.BigDecimal)rows.get(0)[3];String status=(String)rows.get(0)[4];if("PAID".equals(status))return true;if(!"PENDING".equals(status))return true;if(proof.amount()!=PaymentRules.minor(amount)||!"INR".equals(proof.currency())||!"captured".equals(proof.status())||proof.refunded()!=0)throw new ApiException(ErrorCode.PAYMENT_INVALID);jdbc.update("update membership_checkout set status='PAID',gateway_payment_id=?,payment_method=?,paid_at=CURRENT_TIMESTAMP,verified_at=CURRENT_TIMESTAMP where id=?",proof.id(),proof.method(),checkoutId);activate(c,planId);return true;}
 private Subscription activate(UUID customer,UUID planId){var plan=byId(planId);jdbc.update("update customer_memberships set status='CANCELLED',updated_at=CURRENT_TIMESTAMP,version=version+1 where customer_id=? and status='ACTIVE'",customer);Instant start=Instant.now();Instant end=switch(plan.billingPeriod()){case "MONTHLY"->start.plus(30,java.time.temporal.ChronoUnit.DAYS);case "YEARLY"->start.plus(365,java.time.temporal.ChronoUnit.DAYS);default->null;};UUID id=UUID.randomUUID();jdbc.update("insert into customer_memberships(id,customer_id,plan_id,status,starts_at,ends_at) values(?,?,?,'ACTIVE',?,?)",id,customer,planId,Timestamp.from(start),end==null?null:Timestamp.from(end));return new Subscription(id,planId,plan.name(),"ACTIVE",start,end);}
 public Subscription current(UUID userId){UUID c=customer(userId);var rows=jdbc.query("select m.id,m.plan_id,p.name,m.status,m.starts_at,m.ends_at from customer_memberships m join membership_plans p on p.id=m.plan_id where m.customer_id=? and m.status='ACTIVE' order by m.created_at desc limit 1",(r,n)->new Subscription(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getString(3),r.getString(4),r.getTimestamp(5).toInstant(),r.getTimestamp(6)==null?null:r.getTimestamp(6).toInstant()),c);return rows.isEmpty()?null:rows.get(0);}
}
